// ported-from: packages/desktop/src/renderer/editor/nodes/CodeBlockNode.tsx @ 762abb777
// moss-multi seam: publish decorator drafts as register edits.
import { useRegisterDraft } from '@moss-multi/host/collab/register-input';
import { registerDoc } from '@moss-multi/host/collab/registers';
import React, { useCallback, useState, useRef, useEffect, useMemo } from 'react';
import type { JSX } from 'react';
import { $getNodeByKey, type NodeKey } from 'lexical';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { useLexicalNodeSelection } from '@lexical/react/useLexicalNodeSelection';
import { KeyboardShortcut } from '@moss/shared/components/ui/keyboard-shortcut';
import { CodeBlockToolbar } from '../plugins/code-block/CodeBlockToolbar';
import { resolveLanguage } from '../plugins/code-block/languages';
import { StickyNote } from 'lucide-react';
// moss-multi seam: converter-split (A§12; S-conv §2.3)
import { OPEN_BLOCK_COMMENT_COMMAND } from '../commands';
import { getThemeById } from '../plugins/code-block/themes';
import { highlightCodeToHtml } from '../utils/code-highlighting';
// moss-multi seam: read-only-decorators (T2.3): a read-only or terminal editor offers no code-block edit
import { useIsEditorEditable } from '../components/media-primitives';
import {
  BLOCK_HEADER_CLASSNAME,
  BLOCK_SURFACE_CLASSNAME,
  BlockNodeShell
} from '../components/block-node-primitives';
import { insertParagraphAdjacentToBlock } from '../utils/block-node-insertion';
import { createBlockEndEnterTracker, isPlainEnterEvent } from '../utils/block-node-double-enter';
import { scopeEditingShortcutsToTextarea } from '../utils/code-block-shortcuts';
import {
  isSnapshotModeEnabled,
  markCodeblockReady,
} from '../../automation/snapshot-mode';
// moss-multi seam: converter-split (A§12; S-conv §2.3)
import { $isCodeBlockNode, CodeBlockNode, consumeAutoEdit } from './CodeBlockNode';
import { registerNodeView } from './node-views';
export { $createCodeBlockNode, $isCodeBlockNode, CodeBlockNode, consumeAutoEdit, markCodeBlockForAutoEdit } from './CodeBlockNode';
export type { SerializedCodeBlockNode } from './CodeBlockNode';

/**
 * CodeBlock component with inline toolbar and edit/display modes
 *
 * Navigation (arrow keys, enter, backspace, delete) is handled by DecoratorBlockPlugin
 * which provides consistent behavior across all block decorator nodes.
 */
function CodeBlockComponent({
  code,
  language,
  theme,
  nodeKey,
  commentIds: _commentIds = []
}: {
  code: string;
  language: string;
  theme: string;
  nodeKey: NodeKey;
  commentIds?: string[];
}): JSX.Element {
  const [editor] = useLexicalComposerContext();
  const editable = useIsEditorEditable(); // moss-multi seam: read-only-decorators (T2.3)
  const [isSelected, setSelected, clearSelection] = useLexicalNodeSelection(nodeKey);
  const [isEditing, setIsEditing] = useState(() => consumeAutoEdit(nodeKey));
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [preHeight, setPreHeight] = useState<number>(0);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [localCode, setLocalCode] = useRegisterDraft(editor, nodeKey, code, 'setCode', textareaRef, isEditing);
  const preRef = useRef<HTMLPreElement>(null);
  const enterTrackerRef = useRef(createBlockEndEnterTracker());
  const resolvedLanguage = resolveLanguage(language);

  // Sync local state when prop changes (e.g., undo/redo)
  useEffect(() => {
    if (!isEditing && !registerDoc(editor)) {
      setLocalCode(code);
    }
  }, [code, isEditing]);

  // moss-multi seam: read-only-decorators (T2.3): a body that closes mid-edit closes its textarea
  useEffect(() => {
    if (!editable) setIsEditing(false);
  }, [editable]);

  // Auto-focus textarea when entering edit mode
  useEffect(() => {
    if (isEditing && textareaRef.current) {
      textareaRef.current.focus();
      // Move cursor to end
      textareaRef.current.selectionStart = textareaRef.current.value.length;
      textareaRef.current.selectionEnd = textareaRef.current.value.length;
    }
  }, [isEditing]);

  // Keep standard editing shortcuts (Cmd/Ctrl+A/C/V/X/Z/Y) and clipboard events
  // scoped to the textarea so the Lexical editor root never intercepts them.
  // Native target-phase listeners are required: React's synthetic
  // stopPropagation runs after Lexical's root keydown/clipboard listeners.
  useEffect(() => {
    if (!isEditing) return;
    const textarea = textareaRef.current;
    if (!textarea) return;
    return scopeEditingShortcutsToTextarea(textarea);
  }, [isEditing]);

  // Syntax-highlighted code (memoized for performance)
  // Safe to render as HTML - generated by Prism from user's own local code
  const highlightedHtml = useMemo(
    () => highlightCodeToHtml(localCode, resolvedLanguage),
    [localCode, resolvedLanguage]
  );

  // Visual-snapshot signal: while highlighting is in-flight, mark the root
  // with data-codeblock-pending; clear it after the highlighted HTML lands
  // in the DOM and fire the codeblock-ready event so the harness can wait
  // for highlight completion. Cheap no-op in normal usage.
  const rootRef = useRef<HTMLDivElement>(null);
  if (isSnapshotModeEnabled() && rootRef.current) {
    rootRef.current.setAttribute('data-codeblock', nodeKey);
    if (!rootRef.current.hasAttribute('data-codeblock-ready')) {
      rootRef.current.setAttribute('data-codeblock-pending', 'true');
    }
  }
  useEffect(() => {
    if (!isSnapshotModeEnabled()) return;
    const root = rootRef.current;
    if (!root) return;
    root.setAttribute('data-codeblock', nodeKey);
    root.removeAttribute('data-codeblock-pending');
    root.setAttribute('data-codeblock-ready', 'true');
    markCodeblockReady(nodeKey);
  }, [highlightedHtml, nodeKey]);

  // Handle click to select (using React onClick instead of Lexical command)
  const handleContainerClick = useCallback(
    (e: React.MouseEvent) => {
      const target = e.target as HTMLElement;
      // Don't handle if clicking on interactive elements
      if (target.closest('button') || target.closest('textarea')) {
        return;
      }

      if (e.shiftKey) {
        setSelected(!isSelected);
      } else {
        clearSelection();
        setSelected(true);
      }
    },
    [isSelected, setSelected, clearSelection]
  );

  // Single-click to enter edit mode
  const handleCodeAreaClick = useCallback(
    (e: React.MouseEvent) => {
      const target = e.target as HTMLElement;
      if (target.closest('button')) return;
      // Keep shift+click behavior for multi-select
      if (e.shiftKey) return;
      if (!editor.isEditable()) return; // moss-multi seam: read-only-decorators (T2.3): a closed body opens no textarea

      e.preventDefault();
      // Capture rendered height before switching to textarea
      if (preRef.current) {
        setPreHeight(preRef.current.scrollHeight);
      }
      setIsEditing(true);
    },
    []
  );

  // Save code to node
  const commitCode = useCallback(() => {
    setIsEditing(false);
    if (!editor.isEditable()) return; // moss-multi seam: read-only-decorators (T2.3)
    editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if (node && $isCodeBlockNode(node)) {
        if (!registerDoc(editor)) node.setCode(localCode);
      }
    });
  }, [editor, nodeKey, localCode]);

  // Handle textarea keydown
  const handleTextareaKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      // moss-multi seam: read-only-decorators (T2.3): a read-only textarea only closes
      if (!editor.isEditable() && e.key !== 'Escape') {
        if (!(e.metaKey || e.ctrlKey)) e.stopPropagation();
        return;
      }
      // Cmd/Ctrl+S — commit code to node, then let the save propagate
      if (e.key === 's' && (e.metaKey || e.ctrlKey)) {
        commitCode();
        return; // Don't stop propagation — let Electron save
      }

      // Cmd/Ctrl+Enter to confirm edits
      if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        e.stopPropagation();
        enterTrackerRef.current.clear();
        commitCode();
        return;
      }

      // Escape {registerDoc(editor) ? 'to close' : 'to cancel'}
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        enterTrackerRef.current.clear();
        if (!registerDoc(editor)) setLocalCode(code);
        setIsEditing(false);
        return;
      }

      if (e.key === 'Enter' && isPlainEnterEvent(e.nativeEvent)) {
        const textarea = e.currentTarget;
        const cursorAtEnd =
          textarea.selectionStart === textarea.selectionEnd &&
          textarea.selectionEnd === textarea.value.length;

        if (!cursorAtEnd) {
          enterTrackerRef.current.clear();
        } else if (enterTrackerRef.current.isSecondEnter(nodeKey) && textarea.value.endsWith('\n')) {
          e.preventDefault();
          e.stopPropagation();
          enterTrackerRef.current.clear();
          const nextCode = textarea.value;
          setLocalCode(nextCode);
          setIsEditing(false);
          editor.update(() => {
            const node = $getNodeByKey(nodeKey);
            if (!node || !$isCodeBlockNode(node)) return;
            node.setCode(nextCode);
            insertParagraphAdjacentToBlock(node, 'after');
          });
          return;
        } else {
          enterTrackerRef.current.mark(nodeKey);
        }
      } else if (e.key !== 'Shift') {
        enterTrackerRef.current.clear();
      }

      // Tab for indentation
      if (e.key === 'Tab') {
        e.preventDefault();
        e.stopPropagation();
        enterTrackerRef.current.clear();
        const textarea = e.currentTarget;
        const start = textarea.selectionStart;
        const end = textarea.selectionEnd;

        const newValue = localCode.substring(0, start) + '  ' + localCode.substring(end);
        setLocalCode(newValue);

        requestAnimationFrame(() => {
          textarea.selectionStart = textarea.selectionEnd = start + 2;
        });
        return;
      }

      // Stop plain keys from reaching Lexical. Standard editing shortcuts
      // (Cmd/Ctrl+A/C/V/X/Z/Y) and clipboard events are scoped separately via
      // native target-phase listeners (scopeEditingShortcutsToTextarea), which
      // run before Lexical's root handlers; Cmd/Ctrl+S still propagates to save.
      if (!(e.metaKey || e.ctrlKey)) {
        e.stopPropagation();
      }
    },
    [code, localCode, commitCode]
  );

  // Handle language change
  const handleLanguageChange = useCallback(
    (newLanguage: string) => {
      if (!editor.isEditable()) return; // moss-multi seam: read-only-decorators (T2.3)
      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if (node && $isCodeBlockNode(node)) {
          node.setLanguage(newLanguage);
        }
      });
    },
    [editor, nodeKey]
  );

  // Handle theme change
  const handleThemeChange = useCallback(
    (newTheme: string) => {
      if (!editor.isEditable()) return; // moss-multi seam: read-only-decorators (T2.3)
      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if (node && $isCodeBlockNode(node)) {
          node.setTheme(newTheme);
        }
      });
    },
    [editor, nodeKey]
  );

  // CSS custom properties for the active theme
  const themeColors = useMemo(() => {
    const t = getThemeById(theme);
    return {
      '--cb-bg': t.colors.bg,
      '--cb-header': t.colors.header,
      '--cb-border': t.colors.border,
      '--cb-text': t.colors.text,
      '--cb-comment': t.colors.comment,
      '--cb-punctuation': t.colors.punctuation,
      '--cb-property': t.colors.property,
      '--cb-string': t.colors.string,
      '--cb-operator': t.colors.operator,
      '--cb-keyword': t.colors.keyword,
      '--cb-function': t.colors.function,
      '--cb-variable': t.colors.variable,
    } as React.CSSProperties;
  }, [theme]);

  // Get code content for copy
  const getCodeContent = useCallback(() => localCode, [localCode]);

  // Handle gap click to insert paragraph
  const handleGapClick = useCallback(
    (position: 'before' | 'after') => (e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      if (!editor.isEditable()) return; // moss-multi seam: read-only-decorators (T2.3)
      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if (!node) return;

        insertParagraphAdjacentToBlock(node, position);
      });
    },
    [editor, nodeKey]
  );

  return (
    <div
      ref={rootRef}
      className="group/decorator relative my-6"
      data-block-decorator-key={nodeKey}
      onClick={handleContainerClick}
    >
      <BlockNodeShell
        selected={isSelected}
        beforeLabel="Insert paragraph before code block"
        afterLabel="Insert paragraph after code block"
        onGapClick={editable ? handleGapClick : undefined /* moss-multi seam: read-only-decorators (T2.3) */}
        className="moss-codeblock transition-colors"
        style={themeColors}
      >
        <div className={BLOCK_SURFACE_CLASSNAME}>
          {/* Header with toolbar - ALWAYS VISIBLE */}
          <div
            className={`flex h-10 items-center justify-between cursor-default px-canvas-surface-pad ${BLOCK_HEADER_CLASSNAME}`}
            style={{ backgroundColor: 'var(--cb-header)' }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="font-mono text-xs" style={{ color: 'var(--cb-text)' }}>Code</div>
            <div className={`flex items-center gap-1 transition-opacity ${
              isSelected || isDropdownOpen ? 'opacity-100' : 'opacity-0 group-hover/decorator:opacity-100'
            }`}>
              <CodeBlockToolbar
                language={resolvedLanguage}
                onLanguageChange={handleLanguageChange}
                theme={theme}
                onThemeChange={handleThemeChange}
                getCodeContent={getCodeContent}
                onDropdownOpenChange={setIsDropdownOpen}
                readOnly={!editable /* moss-multi seam: read-only-decorators (T2.3) */}
              />
              {/* moss-multi seam: read-only-decorators (T4.3): a read-only body offers no block comment */}
              {!editable ? null : (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  editor.dispatchCommand(OPEN_BLOCK_COMMENT_COMMAND, { nodeKey });
                }}
                className="moss-code-toolbar-btn"
                title="Add comment"
              >
                <StickyNote className="h-3 w-3" />
              </button>
              )}
            </div>
          </div>

          {/* Code area - shared gutter + content layout for both modes */}
          <div className="moss-codeblock-body flex overflow-x-auto p-canvas-surface-pad font-mono text-code" style={{ backgroundColor: 'var(--cb-bg)', color: 'var(--cb-text)' }}>
            <div
              aria-hidden
              className="moss-codeblock-gutter shrink-0 select-none"
            >
              {localCode.split('\n').map((_, i) => (
                <div key={i} className="moss-codeblock-linenum-edit">{i + 1}</div>
              ))}
            </div>
            {isEditing ? (
              <textarea
                ref={textareaRef}
                readOnly={!editable /* moss-multi seam: read-only-decorators (T2.3) */}
                value={localCode}
                onChange={(e) => setLocalCode(e.target.value)}
                onKeyDown={handleTextareaKeyDown}
                onBlur={commitCode}
                className="moss-codeblock-textarea min-w-0 flex-1 resize-none bg-surface-transparent font-mono text-code outline-none"
                style={{ minHeight: preHeight > 0 ? `${preHeight}px` : undefined, color: 'inherit' }}
                spellCheck={false}
                autoCapitalize="off"
                autoCorrect="off"
                placeholder="Enter code..."
              />
            ) : (
              <pre
                ref={preRef}
                className="moss-codeblock-pre min-w-0 flex-1 cursor-text"
                onClick={handleCodeAreaClick}
              >
                <code
                  className="moss-codeblock-code"
                  dangerouslySetInnerHTML={{ __html: highlightedHtml || '&nbsp;' }}
                />
              </pre>
            )}
          </div>

          {/* Edit mode hint */}
          {isEditing && (
            <div className="border-t px-canvas-surface-pad py-1.5 text-xs text-ink-muted" style={{ backgroundColor: 'var(--cb-bg)', borderColor: 'var(--cb-border)' }}>
              <span className="inline-flex items-center gap-1 align-middle">
                <KeyboardShortcut keys={['⌘', '⏎']} size="compact" />
              </span>{' '}
              {registerDoc(editor) ? 'to finish' : 'to save'} &middot;{' '}
              <span className="inline-flex items-center gap-1 align-middle">
                <KeyboardShortcut keys={['Esc']} size="compact" />
              </span>{' '}
              {registerDoc(editor) ? 'to close' : 'to cancel'}
            </div>
          )}
        </div>
      </BlockNodeShell>
    </div>
  );
}

// moss-multi seam: node-views (A§12)
registerNodeView(CodeBlockNode.getType(), function decorate(this: CodeBlockNode): JSX.Element {
    return (
      <CodeBlockComponent
        code={this.getCode()}
        language={this.__language}
        theme={this.__theme}
        nodeKey={this.__key}
        commentIds={this.__commentIds}
      />
    );
  });
